const raw = $input.first().json.output[0].content[0].text;

// ——— 安全提取 JSON 数组 ———
function safeJsonExtract(raw) {
  const match = raw.match(/\[\s*{[\s\S]*?}\s*\]/);
  if (!match) throw new Error("找不到 JSON 数组");
  return JSON.parse(match[0]);
}

let paragraphs = safeJsonExtract(raw);

// ——— 输出 items ———
return paragraphs.map((p, index) => ({
  json: {
    text: p.text ?? p.script,
    order: index + 1,
  }
}));

