// 取出使用者選的 channel & folder
const channel = $('Get_theme').first().json['Channel Name'];
const folder = $('Get_theme').first().json['Folder Name'];

// 取出 AI Agent 的輸出列表
const items = $input.first().json.output;   // <-- 這裡是 array

// 轉成 n8n 多個 item
return items.map(obj => ({
	json: {
		prompt: obj.prompt,
		order: obj.order,
		channel_name: channel,
		folder_name: folder
	}
}));

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.channel_name = $('Get_theme').first().json['Channel Name'];
  item.json.folder_name = $('Get_theme').first().json['Folder Name'];
}

return $input.all();
